sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?album ?releaseDate WHERE {
  VALUES ?album { dbr:Freedom_for_the_Stallion dbr:In_the_Maybe_World }
  OPTIONAL { ?album dbp:released ?released . }
  OPTIONAL { ?album dbp:nextYear ?nextYear . }
  BIND(COALESCE(?released, ?nextYear) AS ?releaseDate)
}
LIMIT 100

